-- schema version 32
CREATE TABLE adf_attestations ( id INTEGER PRIMARY KEY AUTOINCREMENT, issuer TEXT NOT NULL, subject TEXT NOT NULL, role TEXT NOT NULL, issued_at TEXT NOT NULL, expires_at TEXT, scope TEXT, signature TEXT NOT NULL, raw_json TEXT NOT NULL );
CREATE TABLE adf_audit ( id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, start_seq INTEGER, end_seq INTEGER, ref TEXT, entry_count INTEGER NOT NULL, size_bytes INTEGER NOT NULL, data BLOB NOT NULL, created_at INTEGER NOT NULL );
CREATE TABLE adf_config ( id INTEGER PRIMARY KEY CHECK (id = 1), config_json TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE adf_files ( path TEXT PRIMARY KEY, content BLOB NOT NULL, mime_type TEXT, size INTEGER NOT NULL, protection TEXT NOT NULL DEFAULT 'none' CHECK(protection IN ('read_only','no_delete','none')), authorized INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE adf_identity ( purpose TEXT PRIMARY KEY, value BLOB NOT NULL, encryption_algo TEXT DEFAULT 'plain', salt BLOB, kdf_params TEXT, code_access INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE adf_inbox ( id TEXT PRIMARY KEY, message_id TEXT, "from" TEXT NOT NULL, "to" TEXT, reply_to TEXT, network TEXT DEFAULT 'devnet', thread_id TEXT, parent_id TEXT, subject TEXT, content TEXT NOT NULL, content_type TEXT, attachments TEXT, meta TEXT, sender_alias TEXT, recipient_alias TEXT, owner TEXT, card TEXT, return_path TEXT, source TEXT DEFAULT 'mesh', source_context TEXT, sent_at INTEGER, received_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'unread', original_message TEXT );
CREATE TABLE adf_logs ( id INTEGER PRIMARY KEY AUTOINCREMENT, level TEXT NOT NULL DEFAULT 'info', origin TEXT, event TEXT, target TEXT, message TEXT NOT NULL, data TEXT, created_at INTEGER NOT NULL, loop TEXT );
CREATE TABLE adf_loop ( seq INTEGER PRIMARY KEY AUTOINCREMENT, role TEXT NOT NULL, content_json TEXT NOT NULL, model TEXT, tokens TEXT, created_at INTEGER NOT NULL, ord INTEGER, loop TEXT NOT NULL DEFAULT 'main' );
CREATE TABLE adf_meta ( key TEXT PRIMARY KEY, value TEXT NOT NULL, protection TEXT NOT NULL DEFAULT 'none' CHECK(protection IN ('none','readonly','increment')) );
CREATE TABLE adf_outbox ( id TEXT PRIMARY KEY, message_id TEXT, "from" TEXT NOT NULL, "to" TEXT NOT NULL, address TEXT DEFAULT '', reply_to TEXT, network TEXT DEFAULT 'devnet', thread_id TEXT, parent_id TEXT, subject TEXT, content TEXT NOT NULL, content_type TEXT, attachments TEXT, meta TEXT, sender_alias TEXT, recipient_alias TEXT, owner TEXT, card TEXT, return_path TEXT, status_code INTEGER, created_at INTEGER NOT NULL, delivered_at INTEGER, status TEXT NOT NULL DEFAULT 'pending', original_message TEXT );
CREATE TABLE adf_tasks ( id TEXT PRIMARY KEY, tool TEXT NOT NULL, args TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'pending', result TEXT, error TEXT, created_at INTEGER NOT NULL, completed_at INTEGER, origin TEXT, requires_authorization INTEGER NOT NULL DEFAULT 0, executor_managed INTEGER NOT NULL DEFAULT 0, approval_meta TEXT, loop TEXT );
CREATE TABLE adf_timers ( id INTEGER PRIMARY KEY AUTOINCREMENT, schedule_json TEXT NOT NULL, next_wake_at INTEGER NOT NULL, payload TEXT, scope TEXT NOT NULL DEFAULT '["system"]', lambda TEXT, warm INTEGER NOT NULL DEFAULT 0, run_count INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, last_fired_at INTEGER, locked INTEGER NOT NULL DEFAULT 0, expired INTEGER NOT NULL DEFAULT 0, loop TEXT );
